-- public.admin_challenge_metrics
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.admin_challenge_metrics()
 RETURNS TABLE(id uuid, title text, market text, format text, audience text, status text, objective text, content_type text, prize_type text, start_date timestamp with time zone, end_date timestamp with time zone, days integer, prize_amount numeric, prize_currency text, winners_count integer, cpm_target numeric, total_views bigint, posts bigint, creators bigint, posts_with_views bigint, median_views numeric, best_views integer, cash_paid numeric, cash_pending numeric, voucher_paid numeric, voucher_pending numeric, reward_currency text, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'admins only'; end if;
  return query
    with entries as (
      select
        s.challenge_id as cid,
        coalesce(sum(s.logged_views), 0)::bigint as total_views,
        count(s.id)::bigint                      as posts,
        count(distinct s.creator_id)::bigint     as creators,
        count(s.id) filter (where s.logged_views is not null)::bigint as posts_with_views,
        (percentile_cont(0.5) within group (order by s.logged_views)
          filter (where s.logged_views is not null))::numeric          as median_views,
        coalesce(max(s.logged_views), 0)::int    as best_views
      from public.submissions s
      group by s.challenge_id
    ),
    money as (
      select
        r.challenge_id as cid,
        coalesce(sum(r.amount) filter (where r.reward_type <> 'voucher' and r.status = 'distributed'), 0)::numeric as cash_paid,
        coalesce(sum(r.amount) filter (where r.reward_type <> 'voucher' and r.status = 'pending'), 0)::numeric     as cash_pending,
        coalesce(sum(r.amount) filter (where r.reward_type =  'voucher' and r.status = 'distributed'), 0)::numeric as voucher_paid,
        coalesce(sum(r.amount) filter (where r.reward_type =  'voucher' and r.status = 'pending'), 0)::numeric     as voucher_pending,
        (array_agg(r.currency order by r.created_at))[1]                                                           as reward_currency
      from public.rewards r
      where r.challenge_id is not null
      group by r.challenge_id
    )
    select
      c.id, c.title,
      coalesce(co.name, nullif(btrim(coalesce(c.market, '')), '')) as market,
      c.format, c.audience, c.status, c.objective,
      c.content_type, c.prize_type, c.start_date, c.end_date,
      greatest(1, (c.end_date::date - c.start_date::date))::int,
      c.prize_amount, c.prize_currency, c.winners_count, c.cpm_target,
      coalesce(e.total_views, 0)::bigint,
      coalesce(e.posts, 0)::bigint,
      coalesce(e.creators, 0)::bigint,
      coalesce(e.posts_with_views, 0)::bigint,
      e.median_views,
      coalesce(e.best_views, 0)::int,
      coalesce(m.cash_paid, 0)::numeric,
      coalesce(m.cash_pending, 0)::numeric,
      coalesce(m.voucher_paid, 0)::numeric,
      coalesce(m.voucher_pending, 0)::numeric,
      coalesce(m.reward_currency, c.prize_currency, 'GBP'),
      'live'::text
    from public.challenges c
    left join public.communities co on co.id = c.community_id
    left join entries e on e.cid = c.id
    left join money   m on m.cid = c.id
    where c.status <> 'draft'

    union all

    select
      h.id,
      coalesce(h.title, h.ref),
      coalesce(co.name, h.country_code),
      h.cadence,
      lower(h.cohort),
      case h.status when 'done' then 'archived' when 'running' then 'active' else 'upcoming' end,
      case h.objective
        when 'Views' then 'views'
        when 'Number of videos' then 'videos'
        when 'Creativity' then 'creativity'
        when 'Views / Trust' then 'trust'
        else 'views' end,
      case h.content_type
        when 'Free' then 'free'
        when 'Suggested videos' then 'suggested'
        when 'Talking style' then 'talking'
        when 'Hooks' then 'hooks'
        else 'other' end,
      case h.prize_type
        when 'Cash' then 'cash'
        when 'Travel voucher' then 'voucher'
        when 'Cash & Travel voucher' then 'cash_voucher'
        else 'other' end,
      h.starts_at::timestamptz, h.ends_at::timestamptz,
      greatest(1, (h.ends_at - h.starts_at))::int,
      h.prize_total, h.prize_currency, h.winners, null::numeric,
      h.total_views,                    -- NULL stays NULL. See the note above.
      h.posts::bigint,
      h.creators::bigint,
      h.posts::bigint,
      null::numeric,
      0::int,
      -- The prize money was spent; the platform's reward ledger knows nothing
      -- about it, so it is reported as paid cash rather than pretended away.
      coalesce(h.prize_total, 0)::numeric, 0::numeric, 0::numeric, 0::numeric,
      h.prize_currency,
      'history'::text
    from public.challenge_history h
    left join public.communities co on co.id = h.community_id
    where h.challenge_id is null    -- never the same contest twice

    order by start_date desc;
end;
$function$;
